-- Derive the narrow E2 market-support projection from the canonical production
-- V2 SQL. No feature equation is copied into this migration. A definition guard
-- rejects drift until this projection is regenerated by migration replay.
BEGIN;

DO $generate_market_projection$
DECLARE
    definition text;
    query_text text;
    generated_body text;
    start_pos integer;
    end_pos integer;
    alias_name text;
    expression text;
    expressions text[]:=ARRAY[]::text[];
    matches text[];
    anchor text;
BEGIN
    definition:=pg_get_functiondef('feat.build_features_v2_shared(date,date,bigint[])'::regprocedure);
    anchor:='    WITH prior_sessions AS (';
    IF length(definition)-length(replace(definition,anchor,''))<>length(anchor) THEN
        RAISE EXCEPTION 'unexpected V2 daily-input start anchor';
    END IF;
    start_pos:=strpos(definition,anchor);
    anchor:='    ), breadth AS (';
    IF length(definition)-length(replace(definition,anchor,''))<>length(anchor) THEN
        RAISE EXCEPTION 'unexpected V2 daily-input end anchor';
    END IF;
    end_pos:=strpos(definition,anchor);
    IF end_pos<=start_pos THEN RAISE EXCEPTION 'invalid V2 daily-input bounds'; END IF;
    query_text:=substr(definition,start_pos,end_pos-start_pos);

    -- These are the exact final V2 output equations, rather than substitutes
    -- based on similar daily inputs (ret and r1 have distinct source guards).
    FOREACH alias_name IN ARRAY ARRAY['r1','high52_distance','low52_distance'] LOOP
        matches:=regexp_match(definition,'(?n)^               (.+) AS '||alias_name||',$');
        IF matches IS NULL OR cardinality(matches)<>1 THEN
            RAISE EXCEPTION 'unexpected V2 market projection expression %',alias_name;
        END IF;
        expression:=matches[1];
        expressions:=array_append(expressions,expression);
    END LOOP;
    anchor:='        WHERE q.trade_date BETWEEN p_date_from AND p_date_to AND q.c IS NOT NULL';
    IF length(definition)-length(replace(definition,anchor,''))<>length(anchor)
       OR strpos(definition,'r.turnover_now,ln(1+r.turnover_now)')=0 THEN
        RAISE EXCEPTION 'unexpected V2 market output eligibility or turnover projection';
    END IF;
    query_text:=query_text||E'    )\nSELECT q.symbol_id,q.trade_date,''phase2-v2''::text,'
        ||array_to_string(expressions,',')||',q.turnover_now FROM eligible_daily q'
        ||E'\n'||anchor;

    -- Bind dates and scope as values; the only identifier substitution below
    -- is quoted after the shared schema ownership/identifier validation.
    query_text:=replace(query_text,'p_date_from','$1');
    query_text:=replace(query_text,'p_date_to','$2');
    query_text:=replace(query_text,'p_symbol_ids','$3');
    anchor:='FROM pg_temp.phase2_adjustment_rows r';
    IF length(query_text)-length(replace(query_text,anchor,''))<>length(anchor) THEN
        RAISE EXCEPTION 'unexpected V2 market adjustment source';
    END IF;
    query_text:=replace(query_text,anchor,'FROM @PHASE2_INPUT_ROWS@ r');

    generated_body:=format($body$
DECLARE previous_path text; query_text text;
BEGIN
    IF p_date_from IS NULL OR p_date_to IS NULL OR p_date_from>p_date_to THEN
        RAISE EXCEPTION 'valid inclusive date range required';
    END IF;
    IF ops.phase2_hash_text(pg_get_functiondef(
        'feat.build_features_v2_shared(date,date,bigint[])'::regprocedure))<>%L THEN
        RAISE EXCEPTION 'production V2 changed; regenerate the shared market projection';
    END IF;
    previous_path:=feat.phase2_builder_set_context(p_input_schema,p_output_schema,p_ops_schema);
    IF to_regclass(format('%%I.phase2_adjustment_rows',p_input_schema)) IS NULL THEN
        RAISE EXCEPTION 'market projection requires branch-specific adjustment rows';
    END IF;
    query_text:=replace(%L,'@PHASE2_INPUT_ROWS@',format('%%I.phase2_adjustment_rows',p_input_schema));
    RETURN QUERY EXECUTE query_text USING p_date_from,p_date_to,NULL::bigint[];
    PERFORM feat.phase2_builder_restore_context(previous_path);
END
$body$,ops.phase2_hash_text(definition),query_text);

    EXECUTE format($create$
CREATE OR REPLACE FUNCTION feat.phase2_market_inputs_scoped(
    p_date_from date,p_date_to date,p_input_schema text,p_output_schema text,p_ops_schema text
)
RETURNS TABLE(symbol_id bigint,trade_date date,feature_version text,
    ret_1 double precision,distance_52w_high double precision,
    distance_52w_low double precision,turnover_proxy_vnd double precision)
LANGUAGE plpgsql AS %L
$create$,generated_body);
END;
$generate_market_projection$;

COMMENT ON FUNCTION feat.phase2_market_inputs_scoped(date,date,text,text,text) IS
    'Full-universe narrow market support generated from canonical production V2 CTEs and final expressions; branch-specific raw rows, unchanged session/episode/null guards, runtime production-definition drift check.';

COMMIT;
